/**
 * Comprehensive test suite for the Fee Reminder / Dunning Engine.
 *
 * Stage names used throughout:
 *   "D-2"  — 2 days before due date
 *   "D+0"  — due today
 *   "D+3"  — 3 days overdue
 *   "D+7"  — 7 days overdue
 *   "D+14" — 14 days overdue
 *
 * D30 is never generated by the engine; historical D30 rows are preserved.
 */

