// ─────────────────────────────────────────────────────────────────────────────
// 3. daysSinceIST — IST-aware date arithmetic
// ─────────────────────────────────────────────────────────────────────────────

describe("daysSinceIST", () => {
  const DUE = "2027-08-20";

  afterEach(() => vi.useRealTimers());

  it("returns 0 on the due date in IST",   () => { setFakeIST(0,  DUE); expect(daysSinceIST(DUE)).toBe(0); });
  it("returns -2 two days before due",     () => { setFakeIST(-2, DUE); expect(daysSinceIST(DUE)).toBe(-2); });
  it("returns  3 three days after due",    () => { setFakeIST(3,  DUE); expect(daysSinceIST(DUE)).toBe(3); });
  it("returns  7 seven days after due",    () => { setFakeIST(7,  DUE); expect(daysSinceIST(DUE)).toBe(7); });
  it("returns 14 fourteen days after due", () => { setFakeIST(14, DUE); expect(daysSinceIST(DUE)).toBe(14); });

  it("uses IST calendar boundary — UTC 18:29:59 on 19-Aug = IST 23:59 on 19-Aug → day before due", () => {
    // IST today = Aug 19, due = Aug 20 → days = -1
    vi.setSystemTime(new Date("2027-08-19T18:29:59Z"));
    expect(daysSinceIST(DUE)).toBe(-1);
  });
  it("uses IST calendar boundary — UTC 18:30 on 20-Aug = IST 00:00 on 21-Aug → 1 day after due", () => {
    // IST today = Aug 21, due = Aug 20 → days = 1 (NOT on D+0 stage)
    vi.setSystemTime(new Date("2027-08-20T18:30:00Z"));
    expect(daysSinceIST(DUE)).toBe(1);
  });
  it("uses IST calendar boundary — UTC 18:30 on 19-Aug = IST 00:00 on 20-Aug → due today (D+0)", () => {
    // IST today = Aug 20 = due date → days = 0
    vi.setSystemTime(new Date("2027-08-19T18:30:00Z"));
    expect(daysSinceIST(DUE)).toBe(0);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// 4. getStage — exact-day matching
// ─────────────────────────────────────────────────────────────────────────────

describe("getStage — exact-day matching", () => {
  const DUE = "2027-08-20";
  afterEach(() => vi.useRealTimers());

  it("returns D-2 exactly 2 days before due",   () => { setFakeIST(-2, DUE); expect(getStage(DUE)).toBe("D-2");  });
  it("returns D+0 on the due date",             () => { setFakeIST(0,  DUE); expect(getStage(DUE)).toBe("D+0");  });
  it("returns D+3 exactly 3 days overdue",      () => { setFakeIST(3,  DUE); expect(getStage(DUE)).toBe("D+3");  });
  it("returns D+7 exactly 7 days overdue",      () => { setFakeIST(7,  DUE); expect(getStage(DUE)).toBe("D+7");  });
  it("returns D+14 exactly 14 days overdue",    () => { setFakeIST(14, DUE); expect(getStage(DUE)).toBe("D+14"); });

  it("returns null on day 1 (not a stage day)", () => { setFakeIST(1,  DUE); expect(getStage(DUE)).toBeNull(); });
  it("returns null on day 5 (not a stage day)", () => { setFakeIST(5,  DUE); expect(getStage(DUE)).toBeNull(); });
  it("returns null on day 30 — D30 is never generated", () => {
    setFakeIST(30, DUE);
    expect(getStage(DUE)).toBeNull();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// 5. getStageWithCatchup — catch-up window
// ─────────────────────────────────────────────────────────────────────────────

describe("getStageWithCatchup — 2-day catch-up window", () => {
  const DUE = "2027-08-20";
  afterEach(() => vi.useRealTimers());

  it("fires D+7 on the exact day (day 7)",  () => { setFakeIST(7, DUE); expect(getStageWithCatchup(DUE)).toBe("D+7"); });
  it("catches D+7 one day late (day 8)",    () => { setFakeIST(8, DUE); expect(getStageWithCatchup(DUE)).toBe("D+7"); });
  it("catches D+7 two days late (day 9)",   () => { setFakeIST(9, DUE); expect(getStageWithCatchup(DUE)).toBe("D+7"); });
  it("does NOT catch D+7 three days late",  () => { setFakeIST(10, DUE); expect(getStageWithCatchup(DUE)).toBeNull(); });

  it("fires D+0 on exact day",              () => { setFakeIST(0, DUE);  expect(getStageWithCatchup(DUE)).toBe("D+0"); });
  it("catches D+0 one day late (day 1)",    () => { setFakeIST(1, DUE);  expect(getStageWithCatchup(DUE)).toBe("D+0"); });
  it("catches D+0 two days late (day 2)",   () => { setFakeIST(2, DUE);  expect(getStageWithCatchup(DUE)).toBe("D+0"); });
  it("does not generate D30",               () => { setFakeIST(30, DUE); expect(getStageWithCatchup(DUE)).toBeNull(); });
  it("respects custom maxCatchupDays=0 (no catch-up)", () => {
    setFakeIST(8, DUE);
    expect(getStageWithCatchup(DUE, 0)).toBeNull();
  });
  it("respects custom maxCatchupDays=1",    () => {
    setFakeIST(8, DUE);  // 1 day after D+7
    expect(getStageWithCatchup(DUE, 1)).toBe("D+7");
  });
});

