describe("getStageForManualTrigger — nearest bucket", () => {
  const DUE = "2027-08-20";
  afterEach(() => vi.useRealTimers());

  it("days <= -2  → D-2",  () => { setFakeIST(-5,  DUE); expect(getStageForManualTrigger(DUE)).toBe("D-2");  });
  it("day  -2     → D-2",  () => { setFakeIST(-2,  DUE); expect(getStageForManualTrigger(DUE)).toBe("D-2");  });
  it("day  -1     → D+0",  () => { setFakeIST(-1,  DUE); expect(getStageForManualTrigger(DUE)).toBe("D+0");  });
  it("day   0     → D+0",  () => { setFakeIST(0,   DUE); expect(getStageForManualTrigger(DUE)).toBe("D+0");  });
  it("day   1     → D+0",  () => { setFakeIST(1,   DUE); expect(getStageForManualTrigger(DUE)).toBe("D+0");  });
  it("day   2     → D+3",  () => { setFakeIST(2,   DUE); expect(getStageForManualTrigger(DUE)).toBe("D+3");  });
  it("day   5     → D+3",  () => { setFakeIST(5,   DUE); expect(getStageForManualTrigger(DUE)).toBe("D+3");  });
  it("day   6     → D+7",  () => { setFakeIST(6,   DUE); expect(getStageForManualTrigger(DUE)).toBe("D+7");  });
  it("day  10     → D+7",  () => { setFakeIST(10,  DUE); expect(getStageForManualTrigger(DUE)).toBe("D+7");  });
  it("day  11     → D+14", () => { setFakeIST(11,  DUE); expect(getStageForManualTrigger(DUE)).toBe("D+14"); });
  it("day  30     → D+14 (never D30)", () => { setFakeIST(30, DUE); expect(getStageForManualTrigger(DUE)).toBe("D+14"); });
});

